#include <iostream>
#include <map>
#include <string>

int main() {
    const std::map<std::string, long long> byCategory{
        {"transport", 1200},
        {"food", 4000},
    };

    for (const auto& [category, amount] : byCategory) {
        std::cout << category << '\t' << amount << '\n';
    }
}
